-- Export de la table `waypoints`
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS `waypoints`;
CREATE TABLE `waypoints` (
  `entry` int(10) unsigned NOT NULL DEFAULT 0,
  `pointid` int(10) unsigned NOT NULL DEFAULT 0,
  `position_x` float NOT NULL DEFAULT 0,
  `position_y` float NOT NULL DEFAULT 0,
  `position_z` float NOT NULL DEFAULT 0,
  `orientation` float DEFAULT NULL,
  `delay` int(10) unsigned NOT NULL DEFAULT 0,
  `point_comment` mediumtext COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`entry`,`pointid`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci ROW_FORMAT=DYNAMIC COMMENT='Creature waypoints';

